fn solve(x: i8, y: i8, z: i8) -> i8 {
    // Under the preconditions:
    //   x >= 1, y >= 1, z >= 1
    //   y + 2*z <= x
    // we know:
    //   numerator = x - z >= y + z > 0
    //   denominator = y + z > 0
    // and both fit in i8.
    let numerator = x - z;
    let denominator = y + z;
    // Since both numerator and denominator are positive,
    // integer division in Rust rounds toward zero,
    // which for positive values is the same as floor.
    numerator / denominator
}

